/**
 * @title Team and billing settings
 * @description Tabs for General, Members and Billing: workspace details, a members table with roles and invites, the current plan with usage, and invoices.
 * @route /settings/team
 * @height 900
 */
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { DashboardSidebar } from "@/components/dashboard-sidebar";
import { SiteHeader } from "@/components/site-header";
import { TeamSettings } from "@/components/team-settings";

export default function Page() {
  return (
    <SidebarProvider>
      <DashboardSidebar current="Team" />
      <SidebarInset>
        <SiteHeader crumbs={[{ label: "Settings", href: "#" }, { label: "Team" }]} />
        <div className="flex flex-1 flex-col gap-6 p-4 md:p-6">
          <h1 className="text-heading-h2">Team settings</h1>
          <TeamSettings />
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";
import { BarChart3, Camera, Database, FileText, FolderKanban, Gauge, HelpCircle, LayoutDashboard, ListChecks, Search, Settings, Users } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import {
  Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupLabel, SidebarHeader, SidebarMenu, SidebarMenuButton,
  SidebarMenuItem, SidebarRail,
} from "@/components/ui/sidebar";
import { BrandHeader } from "@/components/brand-header";
import { NavSecondary } from "@/components/nav-secondary";
import { NavUser } from "@/components/nav-user";

const main = [
  { title: "Dashboard", icon: LayoutDashboard }, { title: "Lifecycle", icon: ListChecks }, { title: "Analytics", icon: BarChart3 },
  { title: "Projects", icon: FolderKanban }, { title: "Team", icon: Users },
];
const documents = [{ title: "Data library", icon: Database }, { title: "Reports", icon: FileText }, { title: "Capture", icon: Camera }];
const secondary = [{ title: "Settings", url: "#", icon: Settings }, { title: "Get help", url: "#", icon: HelpCircle }, { title: "Search", url: "#", icon: Search }];

/** The app sidebar the dashboard, settings and table blocks share. Pass the current page's title. */
export function DashboardSidebar({ current = "Dashboard", variant = "inset" }: { current?: string; variant?: "sidebar" | "inset" }) {
  return (
    <Sidebar collapsible="icon" variant={variant} label="Main navigation">
      <SidebarHeader>
        <BrandHeader name="Acme Inc" detail="Workspace" logo={Gauge} />
      </SidebarHeader>
      <SidebarContent>
        <nav aria-label="Main" className="contents">
          <SidebarGroup>
            <SidebarMenu>
              {main.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <SidebarGroup>
            <SidebarGroupLabel as="h2">Documents</SidebarGroupLabel>
            <SidebarMenu>
              {documents.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <NavSecondary items={secondary.map((s) => ({ ...s }))} className="mt-auto" />
        </nav>
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={{ name: "Jane Cooper", email: "jane@acme.com" }} />
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  );
}

"use client";
import { GalleryVerticalEnd, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Logo, product name and a second line (plan or version) at the top of the sidebar. Links home. */
export function BrandHeader({ name = "Acme Docs", detail = "v4.0.0", logo = GalleryVerticalEnd }: { name?: string; detail?: string; logo?: LucideIcon }) {
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton href="#" size="lg" tooltip={name}>
          <span className="grid size-8 shrink-0 place-items-center rounded-control bg-brand text-fg-on-brand"><Icon name={logo} size={16} /></span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="truncate text-label-medium text-fg-primary">{name}</span>
            <span className="truncate text-caption-default">{detail}</span>
          </span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { LucideIcon } from "lucide-react";
import type { HTMLAttributes } from "react";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarGroupContent, SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Small links near the bottom of the sidebar (support, feedback). */
export function NavSecondary({ items, ...rest }: HTMLAttributes<HTMLDivElement> & { items: { title: string; url: string; icon: LucideIcon }[] }) {
  return (
    <SidebarGroup {...rest}>
      <SidebarGroupContent>
        <SidebarMenu>
          {items.map((item) => (
            <SidebarMenuItem key={item.title}>
              <SidebarMenuButton href={item.url} size="sm" tooltip={item.title}>
                <Icon name={item.icon} size={16} />
                <span>{item.title}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

"use client";
import { ChevronsUpDown } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";

/** The signed-in person at the bottom of the sidebar, with an account menu. */
export function NavUser({ user }: { user: { name: string; email: string } }) {
  const { isMobile, state } = useSidebar();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <Menu
          label={`Account menu for ${user.name}`}
          className="flex w-full"
          placement={!isMobile && state === "collapsed" ? "right-end" : "top-start"}
          items={[
            { label: "Profile", icon: "user" },
            { label: "Billing", icon: "credit-card" },
            { label: "Notifications", icon: "bell" },
            { label: "Sign out", icon: "sign-out", separatorBefore: true },
          ]}
          trigger={({ ref, ...p }) => (
            <SidebarMenuButton ref={ref as React.Ref<HTMLElement>} {...p} size="lg" tooltip={user.name}>
              <Avatar name={user.name} decorative />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-label-medium text-fg-primary">{user.name}</span>
                <span className="truncate text-caption-default">{user.email}</span>
              </span>
              <Icon name={ChevronsUpDown} size={16} />
            </SidebarMenuButton>
          )}
        />
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { ReactNode } from "react";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { SidebarTrigger } from "@/components/ui/sidebar";

/** The bar above the page: sidebar toggle, breadcrumbs and optional actions on the end side. */
export function SiteHeader({ crumbs, actions }: { crumbs: { label: string; href?: string }[]; actions?: ReactNode }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4 md:rounded-t-[inherit]">
      <SidebarTrigger className="-ms-1" />
      <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
      <Breadcrumbs items={crumbs} />
      {actions && <div className="ms-auto flex items-center gap-2">{actions}</div>}
    </header>
  );
}

"use client";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Avatar, Card } from "@/components/ui/display";
import { Table } from "@/components/ui/data";
import { Badge, Progress } from "@/components/ui/feedback";
import { Select, TextField } from "@/components/ui/form";
import { Tabs } from "@/components/ui/navigation";
import { Menu } from "@/components/ui/overlays";
import { FormActions } from "@/components/ui/patterns";

type Member = { name: string; email: string; role: string; status: "Active" | "Invited" };
const members: Member[] = [
  { name: "Jane Cooper", email: "jane@acme.com", role: "owner", status: "Active" },
  { name: "Wade Warren", email: "wade@acme.com", role: "admin", status: "Active" },
  { name: "Esther Howard", email: "esther@acme.com", role: "member", status: "Active" },
  { name: "Cameron Williamson", email: "cameron@acme.com", role: "member", status: "Invited" },
];
const roles = [{ value: "owner", label: "Owner" }, { value: "admin", label: "Admin" }, { value: "member", label: "Member" }, { value: "viewer", label: "Viewer" }];
const invoices = [
  { id: "INV-2026-011", date: "Nov 1, 2026", amount: "$480.00" },
  { id: "INV-2026-010", date: "Oct 1, 2026", amount: "$480.00" },
  { id: "INV-2026-009", date: "Sep 1, 2026", amount: "$420.00" },
];

function General() {
  return (
    <Card headingLevel={2} title="Workspace">
      <form className="flex max-w-xl flex-col gap-4" onSubmit={(e) => e.preventDefault()}>
        <TextField label="Workspace name" defaultValue="Acme Inc" />
        <TextField label="Workspace URL" defaultValue="acme" helperText="acme.app/acme — changing it breaks old links." />
        <Select label="Default role for new members" defaultValue="member" options={roles.slice(1)} />
        <FormActions />
      </form>
    </Card>
  );
}

function Members() {
  return (
    <div className="flex flex-col gap-4">
      <form className="flex flex-col gap-3 rounded-container border border-line-default bg-surface p-[var(--ds-padding-card)] sm:flex-row sm:items-end" onSubmit={(e) => e.preventDefault()}>
        <div className="flex-1"><TextField label="Invite by email" type="email" placeholder="name@company.com" /></div>
        <div className="sm:w-40"><Select label="Role" defaultValue="member" options={roles.slice(1)} /></div>
        <Button type="submit" leadingIcon="send">Send invite</Button>
      </form>
      <Table<Member>
        caption="Members"
        rows={members}
        rowKey={(m) => m.email}
        columns={[
          { key: "name", header: "Name", render: (m) => <span className="flex items-center gap-3"><Avatar name={m.name} decorative /><span className="flex flex-col"><span className="text-label-medium">{m.name}</span><span className="text-caption-default text-fg-secondary">{m.email}</span></span></span> },
          { key: "role", header: "Role", width: 160, render: (m) => <Select label={`Role for ${m.name}`} hideLabel defaultValue={m.role} options={roles} disabled={m.role === "owner"} /> },
          { key: "status", header: "Status", render: (m) => <Badge tone={m.status === "Active" ? "success" : "warning"}>{m.status}</Badge> },
          { key: "actions", header: "Actions", headerHidden: true, width: 56, render: (m) => <Menu label={`More actions for ${m.name}`} placement={members.indexOf(m) < 2 ? "bottom-end" : "top-end"} items={[{ label: m.status === "Invited" ? "Resend invite" : "View profile", icon: m.status === "Invited" ? "send" : "user" }, { label: "Remove from team", icon: "trash", tone: "danger", separatorBefore: true, disabled: m.role === "owner" }]} /> },
        ]}
      />
    </div>
  );
}

function Billing() {
  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <Card headingLevel={2} title="Plan" actions={<><Button>Upgrade to Business</Button><Button variant="secondary">Compare plans</Button></>}>
        <p className="flex items-baseline gap-2"><span className="text-heading-h2">Pro</span><span className="text-body-small text-fg-secondary">$12 per member / month · renews Dec 1</span></p>
        <Progress value={80} label="Seats (8 of 10)" />
        <Progress value={46} label="Storage (46 of 100 GB)" />
      </Card>
      <Card headingLevel={2} title="Invoices">
        <ul className="flex flex-col divide-y divide-line-default">
          {invoices.map((i) => (
            <li key={i.id} className="flex items-center gap-3 py-2">
              <span className="flex flex-1 flex-col"><span className="text-label-medium">{i.date}</span><span className="text-caption-default text-fg-secondary">{i.id}</span></span>
              <span className="tabular-nums">{i.amount}</span>
              <Button variant="ghost" size="sm" leadingIcon="download" aria-label={`Download ${i.id}`}>PDF</Button>
            </li>
          ))}
        </ul>
      </Card>
    </div>
  );
}

export function TeamSettings() {
  const [tab, setTab] = useState("members");
  return (
    <Tabs label="Team settings" value={tab} onChange={setTab}
      tabs={[
        { id: "general", label: "General", panel: <General /> },
        { id: "members", label: "Members", count: members.length, panel: <Members /> },
        { id: "billing", label: "Billing", panel: <Billing /> },
      ]} />
  );
}
